let saved={seen:[],stars:0};try{const v=JSON.parse(localStorage.getItem('abc-explorer-v1'));if(v&&Array.isArray(v.seen))saved={seen:v.seen.filter(x=>Number.isInteger(x)&&x>=0&&x<26),stars:Number.isFinite(v.stars)?Math.max(0,v.stars):0};}catch{}
const $=s=>document.querySelector(s),area=$('#activity');
function persist(){try{localStorage.setItem('abc-explorer-v1',JSON.stringify(saved));}catch{$('#notice').textContent='当前浏览器无法保存记录，这次仍然可以正常玩。';}}
function stats(){$('#stars').textContent=saved.stars;if($('#visitedCount'))$('#visitedCount').textContent=`${saved.seen.length} / 26`;}
function seen(){if(!saved.seen.includes(index)){saved.seen.push(index);persist();}stats();}
function speakDevice(text){if(!sound)return;if(!('speechSynthesis'in window)){$('#notice').textContent='这台设备暂不支持朗读，可以先玩配对和描写。';return;}const voices=speechSynthesis.getVoices(),english=voices.filter(v=>/^en[-_]/i.test(v.lang));if(voices.length&&!english.length){$('#notice').textContent='设备未安装英语声音，请在系统朗读设置中添加英语。';return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.75;u.pitch=1;u.voice=english.find(v=>v.lang==='en-US')||english[0]||null;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))$('#notice').textContent='没有听到声音？请打开媒体音量，并检查设备的英语朗读设置。';};speechSynthesis.speak(u);}
const audioCache=new Map(),audioSources=new Map(),audioPending=new Map(),audioBlobs=new Map(),audioBuffers=new Map(),audioDecoding=new Map();let currentAudio=null,audioContext=null,currentSource=null,audioRequest=0;
function audioPath(letter){return 'audio/'+letter.toLowerCase()+'.mp3?v=2';}
function letterAudio(letter){if(!audioCache.has(letter)){const a=new Audio(audioSources.get(letter)||audioPath(letter));a.preload='auto';audioCache.set(letter,a);}const a=audioCache.get(letter),ready=audioSources.get(letter);if(ready&&a.src!==ready&&a!==currentAudio)a.src=ready;return a;}
function preloadLetter(letter){if(typeof fetch==='undefined'||typeof URL==='undefined'||typeof URL.createObjectURL!=='function')return Promise.resolve();if(audioSources.has(letter))return Promise.resolve();if(audioPending.has(letter))return audioPending.get(letter);const task=fetch(audioPath(letter)).then(r=>{if(!r.ok)throw Error('Audio unavailable');return r.blob();}).then(blob=>{audioSources.set(letter,URL.createObjectURL(blob));audioBlobs.set(letter,blob);if(audioContext)decodeLetter(letter).catch(()=>{});}).catch(()=>{}).finally(()=>audioPending.delete(letter));audioPending.set(letter,task);return task;}
async function preloadAllLetters(){await preloadLetter(letters[index]);let next=0;await Promise.all(Array.from({length:3},async()=>{while(next<letters.length){const letter=letters[next++];await preloadLetter(letter);}}));}
function unlockAudio(){try{if(navigator.audioSession&&navigator.audioSession.type!=='playback')navigator.audioSession.type='playback';}catch{}const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;try{if(!audioContext||audioContext.state==='closed')audioContext=new Context();if(audioContext.state!=='running')audioContext.resume().catch(()=>{$('#notice').textContent='请点一次「听答案」启用声音。';});for(const letter of audioBlobs.keys())decodeLetter(letter).catch(()=>{});}catch{}}
function decodeLetter(letter){if(audioBuffers.has(letter))return Promise.resolve(audioBuffers.get(letter));if(audioDecoding.has(letter))return audioDecoding.get(letter);const task=(async()=>{await preloadLetter(letter);if(!audioContext||!audioBlobs.has(letter))throw Error('Audio not ready');const bytes=await audioBlobs.get(letter).arrayBuffer();const buffer=await audioContext.decodeAudioData(bytes);audioBuffers.set(letter,buffer);return buffer;})();audioDecoding.set(letter,task);task.finally(()=>audioDecoding.delete(letter)).catch(()=>{});return task;}
function playBuffer(buffer,request){if(!sound||request!==audioRequest||document.hidden||$('#parent').open)return;if(audioContext.state!=='running'){audioContext.resume().then(()=>{if(audioContext.state==='running')playBuffer(buffer,request);else $('#notice').textContent='请点一次「听答案」启用声音。';}).catch(()=>{$('#notice').textContent='请点一次「听答案」启用声音。';});return;}const source=audioContext.createBufferSource();source.buffer=buffer;source.connect(audioContext.destination);currentSource=source;source.onended=()=>{if(currentSource===source)currentSource=null;};source.start();$('#notice').textContent='';}
function playRecordedFallback(text,request){if(request!==audioRequest||!sound)return;if(typeof Audio==='undefined'){speakDevice(text);return;}const a=letterAudio(text);currentAudio=a;a.currentTime=0;a.playbackRate=1;a.play().then(()=>{$('#notice').textContent='';}).catch(error=>{if(currentAudio!==a||request!==audioRequest)return;if(error.name==='NotAllowedError'){$('#notice').textContent='请点一次「听答案」或「听字母」启用声音。';return;}$('#notice').textContent='录音暂时无法播放，正在使用设备朗读。';speakDevice(text);});}
function speak(text){if(!sound)return;stopVoice();unlockAudio();const request=audioRequest;if(/^[A-Z]$/.test(text)){if(audioContext){if(audioBuffers.has(text))playBuffer(audioBuffers.get(text),request);else decodeLetter(text).then(buffer=>playBuffer(buffer,request)).catch(()=>playRecordedFallback(text,request));}else playRecordedFallback(text,request);}else WordAudio.play(text);}
function setAudioStatus(text){const status=$('#audioStatus');if(status)status.textContent=text;}
function stopVoice(){audioRequest++;setAudioStatus('');document.querySelectorAll('[data-block].playing').forEach(b=>b.classList.remove('playing'));if(currentSource){try{currentSource.stop();}catch{}currentSource=null;}if(currentAudio){currentAudio.pause();currentAudio.currentTime=0;currentAudio=null;}if('speechSynthesis'in window)speechSynthesis.cancel();}
function alphabet(){$('#alphabet').innerHTML=letters.map((l,i)=>`<button aria-label="认识字母 ${l}" aria-pressed="${i===index}" class="${i===index?'selected ':''}${saved.seen.includes(i)?'seen':''}" data-letter="${i}">${l}</button>`).join('');}
function clearFamilyRepeat(){if(familyRepeatTimer!==null){clearTimeout(familyRepeatTimer);familyRepeatTimer=null;}}
function scheduleFamilyRepeat(delay=5000){clearFamilyRepeat();if(mode!=='family'||!sound||document.hidden||$('#parent').open)return;const card=quizNumber;familyRepeatTimer=setTimeout(()=>{familyRepeatTimer=null;if(mode!=='family'||quizNumber!==card||!sound||document.hidden||$('#parent').open)return;speak(letters[quizLetter]);scheduleFamilyRepeat(1000);},delay);}
function setMode(next){if(!['learn','listen','match','trace','family','phonics'].includes(next))throw Error('Invalid activity');clearFamilyRepeat();stopVoice();$('#notice').textContent='';if(next==='family'||next==='trace')unlockAudio();if(mode==='phonics'&&next!=='phonics'){Phonics.leave();document.querySelector('aside').innerHTML=originalAside;}mode=next;round=null;document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});render();}
function chooseLetter(i){if(!Number.isInteger(i)||i<0||i>25)throw Error('Invalid letter');index=i;if(mode==='listen'||mode==='match'||mode==='family')setMode('learn');else render();}
const originalAside=document.querySelector('aside').innerHTML;
function render(){if(mode==='phonics'){if(paintCleanup){paintCleanup();paintCleanup=null;}Phonics.render();stats();return;}if(paintCleanup){paintCleanup();paintCleanup=null;}if(mode==='learn'){seen();area.innerHTML=`<div class="activity-top"><span>认识一个新朋友</span><span class="pill">${index+1} / 26</span></div><div class="letter-stage"><span class="big-letter">${letters[index]}</span><span class="big-letter lower">${letters[index].toLowerCase()}</span></div><div class="word"><span class="emoji" role="img" aria-label="${chinese[index]}">${emojis[index]}</span><div><b>${words[index]}</b><small>${chinese[index]}</small></div></div><div class="controls"><button class="primary" id="hear">♫ 听字母</button><button class="secondary" id="hearWord">听单词</button></div><div class="bottom-controls"><button class="round-btn" id="prev" aria-label="上一个字母">‹</button><span>大写和小写，是同一个朋友</span><button class="round-btn" id="next" aria-label="下一个字母">›</button></div>`;$('#hear').textContent='♫ 听字母名称';$('#hear').onclick=()=>speak(letters[index]);$('#hearWord').onclick=()=>speak(words[index]);$('#prev').onclick=()=>chooseLetter((index+25)%26);$('#next').onclick=()=>chooseLetter((index+1)%26);}else if(mode==='trace')renderTrace();else if(mode==='family'){if(quizLetter===null)nextFamilyLetter();renderFamily();}else{if(!round)makeRound();renderQuestion();}alphabet();stats();if(typeof Audio!=='undefined'){const target=mode==='family'?quizLetter:mode==='listen'&&round&&round.step<5?round.targets[round.step]:index;preloadLetter(letters[target]);}}
function shuffle(a){const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
function makeRound(){const recent=saved.seen.length?saved.seen:[index];const pool=[...new Set([...recent.slice(-4),index,...shuffle(Array.from({length:26},(_,i)=>i)).slice(0,2)])];round={targets:Array.from({length:5},()=>pool[Math.floor(Math.random()*pool.length)]),step:0,attempts:0,first:0,answered:false,awarded:false,options:[]};}
function displayAnswer(i){return mode==='listen'&&!listenLower?letters[i]:letters[i].toLowerCase();}
function renderQuestion(){if(round.step===5){if(!round.awarded){saved.stars++;round.awarded=true;persist();}stats();area.innerHTML=`<div class="finish"><div class="award">✦</div><h2>探险完成，收下一颗星！</h2><p>练习了 5 次 · ${round.first} 次第一次就找到了<br>每一次尝试，都在帮你认识字母。</p><button class="primary" id="again">再玩一轮</button><div class="controls"><button class="secondary" id="rest">休息一下，看看字母</button></div></div>`;$('#again').onclick=()=>{makeRound();renderQuestion();};$('#rest').onclick=()=>setMode('learn');return;}const target=round.targets[round.step];round.answered=false;round.attempts=0;const distractors=shuffle(Array.from({length:26},(_,i)=>i).filter(i=>i!==target)).slice(0,mode==='listen'?5:2);round.options=shuffle([target,...distractors]);area.innerHTML=`<div class="activity-top"><span>${mode==='listen'?'听音小探险':'给字母找朋友'}</span><span class="pill">第 ${round.step+1} / 5 题</span></div><div class="progress"><span style="width:${round.step*20}%"></span></div>${mode==='listen'?`<div class="listen-case" role="group" aria-label="选择字母大小写"><button id="listenUpper" aria-pressed="${!listenLower}" class="${!listenLower?'on':''}">ABC 大写字母</button><button id="listenLower" aria-pressed="${listenLower}" class="${listenLower?'on':''}">abc 小写字母</button></div>`:''}<div class="question"><h2>${mode==='listen'?'听一听，找到了吗？':'哪个小写是它的朋友？'}</h2>${mode==='listen'?'<p>先点按钮听字母，再选下面的卡片</p><div class="controls"><button class="primary" id="playQuestion">♫ 听题目</button></div>':`<div class="target">${letters[target]}</div>`}</div><div class="choices ${mode==='listen'?'six-choices':''}">${round.options.map(i=>`<button class="choice" data-answer="${i}" aria-label="选择 ${displayAnswer(i)}">${displayAnswer(i)}</button>`).join('')}</div><div class="feedback" id="feedback" role="status" aria-live="polite">慢慢来，你可以的。</div><div class="controls"><button class="secondary" id="hint">给我一个提示</button><button class="primary" id="continue" hidden>下一题</button></div>`;if(mode==='listen'){ $('#listenUpper').onclick=()=>{listenLower=false;stopVoice();renderQuestion();};$('#listenLower').onclick=()=>{listenLower=true;stopVoice();renderQuestion();};}if($('#playQuestion'))$('#playQuestion').onclick=()=>speak(letters[target]);$('#hint').onclick=()=>{round.attempts++;$('#feedback').textContent=`找找 ${displayAnswer(target)} 这张卡片。`;speak(letters[target]);};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer),b));$('#continue').onclick=()=>{stopVoice();round.step++;renderQuestion();};}
function answer(i,b){if(round.answered)return;round.attempts++;if(i===round.targets[round.step]){round.answered=true;if(round.attempts===1)round.first++;b.classList.add('correct');$('#feedback').textContent='找到了！你和这个字母成为朋友啦。';document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);$('#hint').hidden=true;$('#continue').hidden=false;}else{b.classList.add('wrong');$('#feedback').textContent='再听一听，换一个试试看。';if(mode==='listen')speak(letters[round.targets[round.step]]);}}
function nextFamilyLetter(){if(!quizDeck.length){quizDeck=shuffle(Array.from({length:26},(_,i)=>i));if(quizDeck[quizDeck.length-1]===quizLetter)[quizDeck[0],quizDeck[quizDeck.length-1]]=[quizDeck[quizDeck.length-1],quizDeck[0]];}quizLetter=quizDeck.pop();quizLower=quizCase==='lower'||(quizCase==='mixed'&&Math.random()<.5);quizNumber++;preloadLetter(letters[quizLetter]);}
function setFamilyCase(value){if(!['upper','lower','mixed'].includes(value))throw Error('Invalid letter case');stopVoice();quizCase=value;quizDeck=[];nextFamilyLetter();renderFamily();}
function renderFamily(){const shown=quizLower?letters[quizLetter].toLowerCase():letters[quizLetter];area.innerHTML=`<div class="activity-top"><span>家长考一考</span><span class="pill">第 ${quizNumber} 张</span></div><div class="family-case" role="group" aria-label="出题字母类型">${[['upper','ABC 大写'],['lower','abc 小写'],['mixed','Aa 混合']].map(([value,label])=>`<button data-family-case="${value}" aria-pressed="${quizCase===value}" class="${quizCase===value?'on':''}">${label}</button>`).join('')}</div><div class="family-letter" aria-label="字母 ${shown}">${shown}</div><p class="trace-note">问问孩子：这个字母叫什么？</p><div class="controls"><button class="primary" id="familyNext">换一个字母</button><button class="secondary" id="familyHear">♫ 听答案</button></div><p class="family-note">先让孩子说；停留 5 秒后会朗读，之后每隔 1 秒重复。</p>`;document.querySelectorAll('[data-family-case]').forEach(b=>b.onclick=()=>setFamilyCase(b.dataset.familyCase));$('#familyNext').onclick=()=>{stopVoice();nextFamilyLetter();renderFamily();};$('#familyHear').onclick=()=>speak(letters[quizLetter]);scheduleFamilyRepeat();}
function renderTrace(){area.innerHTML=`<div class="activity-top"><span>跟着浅色字母，用手指描一描</span><div class="trace-case"><button id="upper" class="${!lower?'on':''}">ABC 大写</button><button id="lower" class="${lower?'on':''}">abc 小写</button></div></div><div class="trace-wrap"><span class="trace-guide" aria-hidden="true">${lower?letters[index].toLowerCase():letters[index]}</span><canvas id="canvas" aria-label="字母 ${letters[index]} 的自由描写区"></canvas></div><p class="trace-note">手指或鼠标都可以画，按住再移动。</p><div class="controls"><button class="secondary" id="clear">重新描</button><button class="primary" id="traceNext">下一个字母</button></div><div class="bottom-controls"><button class="round-btn" id="tracePrev" aria-label="上一个字母">‹</button><span>这是自由描写，不评分哦</span><button class="round-btn" id="traceHear" aria-label="听当前字母">♫</button></div>`;$('#upper').onclick=()=>{lower=false;render();};$('#lower').onclick=()=>{lower=true;render();};$('#traceNext').onclick=()=>chooseLetter((index+1)%26);$('#tracePrev').onclick=()=>chooseLetter((index+25)%26);$('#traceHear').onclick=()=>speak(letters[index]);const c=$('#canvas'),ctx=c.getContext('2d');let drawing=false;const resize=()=>{const r=c.getBoundingClientRect(),d=window.devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;ctx.setTransform(d,0,0,d,0,0);ctx.strokeStyle='#215848';ctx.lineWidth=13;ctx.lineCap='round';ctx.lineJoin='round';};resize();const pos=e=>{const r=c.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top];};c.onpointerdown=e=>{drawing=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...pos(e));ctx.lineTo(...pos(e));ctx.stroke();};c.onpointermove=e=>{if(drawing){ctx.lineTo(...pos(e));ctx.stroke();}};c.onpointerup=c.onpointercancel=c.onlostpointercapture=()=>drawing=false;$('#clear').onclick=()=>ctx.clearRect(0,0,c.width,c.height);window.addEventListener('resize',resize);paintCleanup=()=>window.removeEventListener('resize',resize);speak(letters[index]);}
document.addEventListener('click',()=>{if(sound)unlockAudio();},{capture:true});document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelector('aside').onclick=e=>{const b=e.target.closest('[data-letter]');if(b)chooseLetter(Number(b.dataset.letter));};$('.brand').onclick=e=>{e.preventDefault();setMode('learn');};$('#sound').onclick=()=>{sound=!sound;if(sound)unlockAudio();if(!sound){clearFamilyRepeat();stopVoice();}else if(mode==='family')scheduleFamilyRepeat();$('#sound').textContent=sound?'♫ 声音开':'♫ 声音关';$('#sound').setAttribute('aria-pressed',String(sound));};$('#parentOpen').onclick=()=>{clearFamilyRepeat();stopVoice();$('#parent').showModal();};$('#parentClose').onclick=()=>$('#parent').close();$('#parent').addEventListener('close',()=>scheduleFamilyRepeat());document.addEventListener('visibilitychange',()=>{if(document.hidden){clearFamilyRepeat();stopVoice();}else scheduleFamilyRepeat();});window.addEventListener('pagehide',()=>{clearFamilyRepeat();stopVoice();});$('#reset').onclick=()=>{if($('#reset').dataset.confirm!=='yes'){$('#reset').dataset.confirm='yes';$('#reset').textContent='再点一次，确认清除';return;}saved={seen:[],stars:0};Phonics.reset();persist();stats();if(mode==='phonics')Phonics.render();else alphabet();$('#resetStatus').textContent='本机记录已清除。';$('#reset').textContent='清除本机学习记录';delete $('#reset').dataset.confirm;};render();preloadAllLetters();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_letter_activity',title:'打开字母练习',description:'打开所选英文字母的认识或自由描写活动。不会判定掌握情况。',inputSchema:{type:'object',properties:{letter:{type:'string',pattern:'^[A-Za-z]$'},activity:{type:'string',enum:['learn','trace']}},required:['letter','activity'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.letter!=='string'||!/^[A-Za-z]$/.test(input.letter)||!['learn','trace'].includes(input.activity))throw Error('请选择一个英文字母和有效活动');index=letters.indexOf(input.letter.toUpperCase());setMode(input.activity);return{letter:letters[index],activity:mode};}})).catch(()=>{});}catch{}}
